<?php
require_once '../../middleware/jsonMiddleware.php';require_once '../../middleware/requestLogger.php';require_once '../../middleware/corsMiddleware.php';require_once '../../middleware/authMiddleware.php';require_once '../../utils/response.php';require_once '../../config/database.php';use MongoDB\BSON\ObjectId;use MongoDB\BSON\UTCDateTime;
setJsonResponse();handleCors();logRequest();requireLogin();if($_SERVER['REQUEST_METHOD']!=='POST')sendResponse(false,'Method not allowed.',null,405);$d=json_decode(file_get_contents('php://input'),true);$id=trim($d['id']??'');$method=trim($d['method']??'Demo');if(!preg_match('/^[a-f0-9]{24}$/i',$id))sendResponse(false,'Invalid booking.',null,400);try{$db=getDatabase();$b=$db->bookings->findOne(['_id'=>new ObjectId($id),'userId'=>new ObjectId($_SESSION['user_id'])]);if(!$b)sendResponse(false,'Booking not found.',null,404);if(($b['status']??'')!=='Approved')sendResponse(false,'Payment is available only after admin approval.',null,409);$db->bookings->updateOne(['_id'=>$b['_id']],['$set'=>['status'=>'Confirmed','paymentStatus'=>'Paid (Demo)','paymentMethod'=>$method,'paidAt'=>new UTCDateTime()]]);sendResponse(true,'Demo payment successful. Your booking is confirmed!');}catch(Exception $e){error_log('Payment error: '.$e->getMessage());sendResponse(false,'Payment could not be completed.',null,500);}
